From ab234a961c0a86d3109bcc7a0898b5792851d6d6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:46:28 +0100
Subject: [PATCH] applets/quicklaunch: add an option to open the popup on hover

The popup with the extra launchers could only be opened by clicking its
arrow. A new "Open popup on hover" option opens it when the pointer rests
on the arrow and closes it again once the pointer leaves arrow and popup.

BUG: 498275
---
 applets/quicklaunch/ConfigGeneral.qml |  7 +++++
 applets/quicklaunch/main.qml          | 43 ++++++++++++++++++++++++++-
 applets/quicklaunch/main.xml          |  3 ++
 3 files changed, 52 insertions(+), 1 deletion(-)

diff --git a/applets/quicklaunch/ConfigGeneral.qml b/applets/quicklaunch/ConfigGeneral.qml
index 11b6b38a9..b15a96f28 100644
--- a/applets/quicklaunch/ConfigGeneral.qml
+++ b/applets/quicklaunch/ConfigGeneral.qml
@@ -21,6 +21,7 @@ KCM.SimpleKCM {
     property alias cfg_maxSectionCount: maxSectionCount.value
     property alias cfg_showLauncherNames: showLauncherNames.checked
     property alias cfg_enablePopup: enablePopup.checked
+    property alias cfg_popupOnHover: popupOnHover.checked
     property alias cfg_title: title.text

     Kirigami.FormLayout {
@@ -49,6 +50,12 @@ KCM.SimpleKCM {
             text: i18nc("@option:check", "Enable popup")
         }

+        QQC2.CheckBox {
+            id: popupOnHover
+            enabled: enablePopup.checked
+            text: i18nc("@option:check", "Open popup on hover")
+        }
+

         Item {
             Kirigami.FormData.isSection: true
diff --git a/applets/quicklaunch/main.qml b/applets/quicklaunch/main.qml
index 012b52556..021b78c89 100644
--- a/applets/quicklaunch/main.qml
+++ b/applets/quicklaunch/main.qml
@@ -22,6 +22,7 @@ PlasmoidItem {
     readonly property int maxSectionCount: Plasmoid.configuration.maxSectionCount
     readonly property bool showLauncherNames : Plasmoid.configuration.showLauncherNames
     readonly property bool enablePopup : Plasmoid.configuration.enablePopup
+    readonly property bool popupOnHover : enablePopup && Plasmoid.configuration.popupOnHover
     readonly property string title : Plasmoid.formFactor == PlasmaCore.Types.Planar ? Plasmoid.configuration.title : ""
     readonly property bool vertical : Plasmoid.formFactor == PlasmaCore.Types.Vertical || (Plasmoid.formFactor == PlasmaCore.Types.Planar && height > width)
     readonly property bool horizontal : Plasmoid.formFactor == PlasmaCore.Types.Horizontal
@@ -118,6 +119,9 @@ PlasmoidItem {

         PlasmaCore.Dialog {
             id: popup
+
+            property bool openedByHover: false
+
             type: PlasmaCore.Dialog.PopupMenu
             flags: Qt.WindowStaysOnTopHint
             hideOnWindowDeactivate: true
@@ -128,6 +132,37 @@ PlasmoidItem {
                 Keys.onEscapePressed: popup.visible = false
                 launcherModel: launcherModel
                 logic: logic
+
+                HoverHandler {
+                    id: popupHoverHandler
+                }
+            }
+
+            onVisibleChanged: {
+                if (!visible) {
+                    openedByHover = false;
+                }
+            }
+        }
+
+        Timer {
+            id: hoverTimer
+            interval: Kirigami.Units.longDuration
+            readonly property bool hovered: arrowMouseArea.containsMouse || popupHoverHandler.hovered
+            onHoveredChanged: {
+                if (root.popupOnHover && hovered !== popup.visible && (hovered || popup.openedByHover)) {
+                    restart();
+                } else {
+                    stop();
+                }
+            }
+            onTriggered: {
+                if (hovered && !popup.visible) {
+                    popup.openedByHover = true;
+                    popup.visible = true;
+                } else if (!hovered && popup.openedByHover) {
+                    popup.visible = false;
+                }
             }
         }

@@ -147,6 +182,7 @@ PlasmoidItem {
             MouseArea {
                 id: arrowMouseArea
                 anchors.fill: parent
+                hoverEnabled: root.popupOnHover

                 activeFocusOnTab: parent.visible

@@ -164,7 +200,12 @@ PlasmoidItem {
                 Accessible.role: Accessible.Button

                 onClicked: {
-                    popup.visible = !popup.visible
+                    hoverTimer.stop();
+                    if (popup.openedByHover) {
+                        popup.openedByHover = false;
+                    } else {
+                        popup.visible = !popup.visible;
+                    }
                 }

                 Kirigami.Icon {
diff --git a/applets/quicklaunch/main.xml b/applets/quicklaunch/main.xml
index 71528c90e..afd68a265 100644
--- a/applets/quicklaunch/main.xml
+++ b/applets/quicklaunch/main.xml
@@ -15,6 +15,9 @@
     <entry name="enablePopup" type="Bool">
       <default>false</default>
     </entry>
+    <entry name="popupOnHover" type="Bool">
+      <default>false</default>
+    </entry>
     <entry name="title" type="String">
       <default></default>
     </entry>
-- 
2.53.0
